#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

class Solution {
public:
    vector<int> countSubgraphsForEachDiameter(int n, vector<vector<int>>& edges) {
        vector<vector<int>> g(n);
        for (auto& e : edges) {
            g[e[0] - 1].push_back(e[1] - 1);
            g[e[1] - 1].push_back(e[0] - 1);
        }

        vector<int> res(n - 1);
        for (int mask = 1; mask < (1 << n); ++mask) {
            vector<int> nodes;
            for (int i = 0; i < n; ++i)
                if (mask & (1 << i)) nodes.push_back(i);
            if (nodes.size() < 2) continue;

            unordered_set<int> seen;
            queue<int> q;
            q.push(nodes[0]);
            seen.insert(nodes[0]);

            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : g[u])
                    if ((mask & (1 << v)) && !seen.count(v)) {
                        seen.insert(v);
                        q.push(v);
                    }
            }

            if (seen.size() != nodes.size()) continue;

            int maxDist = 0;
            for (int u : nodes) {
                vector<int> dist(n, -1);
                queue<int> q;
                q.push(u);
                dist[u] = 0;
                while (!q.empty()) {
                    int x = q.front(); q.pop();
                    for (int v : g[x])
                        if ((mask & (1 << v)) && dist[v] == -1) {
                            dist[v] = dist[x] + 1;
                            maxDist = max(maxDist, dist[v]);
                            q.push(v);
                        }
                }
            }

            if (maxDist > 0) res[maxDist - 1]++;
        }
        return res;
    }
};
